	// Run Allow concurrently to detect races.
	clock := newFakeClock(time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC))
	l, err := New(Config{Capacity: 1000, RefillPerSecond: 1000}, Dependencies{Clock: clock})
	if err != nil {
